import { Effect } from "effect";
import { SqlClient } from "effect/sql";
// Who is reading a person's role on a repository from GitHub now (decision 0079 §5, worker/github/RepoRoles.ts): one
// request at a time per row claims the read until `read_until`, asks GitHub outside any transaction, and clears it.
// The others wait for the row the read records, polling, never inside a transaction or on a lock, so a burst for one
// expired row holds no Postgres connection while GitHub answers. A read GitHub failed or overran keeps the claim to the
// end of its cooldown (`read_failed`), so the next is refused with its wait rather than asked again. A claim for a
// person with no row yet makes one that decides nothing: no role, checked at `-infinity`, never fresh.
export default Effect.gen(function* () {
    const sql = yield* SqlClient.SqlClient;
    // Each ALTER takes the table's ACCESS EXCLUSIVE lock: a deploy that can't get it soon fails and is run again, rather
    // than queueing every role read behind a long transaction.
    yield* sql `SET LOCAL lock_timeout = '5s'`;
    yield* sql `ALTER TABLE github_repo_roles ADD COLUMN read_until timestamptz`;
    yield* sql `ALTER TABLE github_repo_roles ADD COLUMN read_failed boolean NOT NULL DEFAULT false`;
});
